from prometheus_client import Counter, Gauge, Histogram

TRAFFIC = Counter("requests_total", "Traffic")
ERRORS = Counter("request_errors_total", "Errors")
LATENCY = Histogram("request_seconds", "Latency")
INFLIGHT = Gauge("requests_in_flight", "Saturation")
def handle(req):
    TRAFFIC.inc()
    with INFLIGHT.track_inprogress(), LATENCY.time():
        try:
            return process(req)
        except Exception:
            ERRORS.inc()
            raise

